def moe_predict(X, V, weights_list, sigmas):
    """Prédiction du MoE: y_hat = sum_k g_k(x) * w_k^T x."""
    g = softmax_gating(X, V)
    mu = expert_predictions(X, weights_list, sigmas)
    return (g * mu).sum(axis=1)
